from pathlib import Path
import csv,json,datetime
root=Path(__file__).parent
now=datetime.datetime.now(datetime.timezone.utc).isoformat()
def package(key,rid,sid,pid,title,doi,sha,version,reference,ics,qa,outs,cautions,synthesis):
 out=root/key;out.mkdir(exist_ok=True);base={'Record ID':rid,'Study ID':sid,'Report ID':pid};url='https://arxiv.org/pdf/'+('2505.01968v2' if rid=='R01586' else '2503.02550v3')
 def save(name,rs):
  with(out/name).open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rs[0]));w.writeheader();w.writerows(rs)
 save('Source.csv',[dict(base,Title=title,DOI=doi,Source_URL=url,Source_SHA256=sha,Version=version,Published_identity_URL='https://link.springer.com/chapter/'+doi,Reference=reference,Checked_UTC=now)])
 save('Eligibility.csv',[dict(base,Criterion='IC'+str(i+1),Result='Met',Rationale=why,Anchor=a,Decision='Include',Review_method='Single source-based adjudication under logged amendment; independent human vote not asserted') for i,(why,a) in enumerate(ics)])
 save('QA.csv',[dict(base,Criterion='Q'+str(i+1),Score=s,Applicable_maximum=m,Rationale=r,Anchor=a,Source_URL=url,Source_SHA256=sha,Checked_UTC=now,Independent_score='') for i,(s,m,r,a) in enumerate(qa)])
 save('Outcomes.csv',[dict(base,Metric=m,Value=v,Unit=u,Context=c,Comparator=b,Limitations=l,Anchor=a,Source_URL=url,Source_SHA256=sha) for m,v,u,c,b,l,a in outs])
 save('Cautions.csv',[dict(base,Issue=i,Meaning=m,Anchor=a) for i,m,a in cautions])
 (out/'Synthesis.md').write_text(synthesis+'\n')
 (out/'Reference.txt').write_text(reference+'\nDOI: '+doi+'\n')
 (out/'Validation.json').write_text(json.dumps(dict(record=rid,study=sid,report=pid,IC_rows=len(ics),QA_rows=len(qa),QA_score=sum(q[0] for q in qa if isinstance(q[0],int)),QA_applicable_maximum=sum(q[1] for q in qa),outcomes=len(outs),PDF_in_git=False),indent=2)+'\n')
 print(out)
